class PaymentMethod(ABC):
    @abstractmethod
    def fee(self, amount):
        """Return the fee for this amount."""

    def charge(self, amount):
        return amount + self.fee(amount)


class UPI(PaymentMethod):
    def fee(self, amount):
        return 0


class Card(PaymentMethod):
    def fee(self, amount):
        return max(5, round(amount * 0.02, 2))

