class UPI:
    def charge(self, amount):
        return amount


class Card:
    def charge(self, amount):
        return round(amount * 1.02, 2)


class Order:
    def __init__(self, payment):
        self.payment = payment
        self.items = []

    def add(self, name, price, qty=1):
        self.items.append((name, price, qty))

    def total(self):
        return sum([price * qty for name, price, qty in self.items])

    def checkout(self):
        return self.payment.charge(self.total())


order = Order(UPI())
order.add("Masala chai", 20, 2)
order.add("Samosa", 15)
print(order.total(), order.checkout())
